# Deduplicate by (zip, city, county) while preserving the richest data
normalized_dict = {}
for r in florida_records:
    zip_val = str(r["zip"]).strip()
    city_val = str(r.get("City", "")).strip().upper()
    key = f"{zip_val}_{city_val}"
    
    # Fill in standardized fields
    entry = {
        "_id": r["_id"],
        "zip": int(zip_val) if zip_val.isdigit() else zip_val,
        "City": r.get("City", "").strip().upper(),
        "County": r.get("County", "").strip().upper(),
        "State": "FL",
        "PAlink": r.get("PAlink"),
        "PermitByCounty": r.get("PermitByCounty"),
        "PermitByCity": r.get("PermitByCity"),
        "lat": r.get("lat"),
        "long": r.get("long"),
        "Terrain": r.get("Terrain", "B").strip().upper(),
        "LastUpdated": "2026-03-20"
    }
    
    if key not in normalized_dict:
        normalized_dict[key] = entry
    else:
        # merge fields if missing
        existing = normalized_dict[key]
        if not existing.get("PermitByCity") and entry.get("PermitByCity"):
            existing["PermitByCity"] = entry["PermitByCity"]
        if not existing.get("PermitByCounty") and entry.get("PermitByCounty"):
            existing["PermitByCounty"] = entry["PermitByCounty"]
        if not existing.get("PAlink") and entry.get("PAlink"):
            existing["PAlink"] = entry["PAlink"]

final_list = list(normalized_dict.values())
# Sort by County, City, ZIP
final_list.sort(key=lambda x: (x.get("County", ""), x.get("City", ""), str(x.get("zip", ""))))

ts_output = f"""import {{ FloridaZipRecord }} from '../types/permits';

export const INITIAL_FLORIDA_PERMIT_DATASET: FloridaZipRecord[] = {json.dumps(final_list, indent=2)};
"""

with open('src/data/initialPermitRecords.ts', 'w') as f:
    f.write(ts_output)

print(f"Exported {len(final_list)} unique normalized Florida records.")
